cardCss:
* { box-sizing: border-box; }
.card {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", sans-serif;
  font-size: 16px;
  line-height: 1.78;
  color: #273548;
  background: #f5f7fa;
  text-align: left;
  padding: 18px 12px 30px;
  margin: 0;
}
.quiz-card {
  width: min(100%, 780px);
  margin: 0 auto;
  padding: 24px 24px 22px;
  background: #ffffff;
  border: 1px solid #e8edf3;
  border-radius: 18px;
  box-shadow: 0 10px 30px rgba(39, 53, 72, .06);
  overflow: hidden;
}
.qz-top-line {
  height: 4px;
  margin: -24px -24px 18px;
  background: linear-gradient(90deg, #8bb8d3 0%, #bad8e8 58%, #f2d98b 100%);
}
.qz-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 15px;
}
.qz-kicker {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 3px 10px;
  border-radius: 999px;
  background: #edf5fa;
  color: #4f7892;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 750;
  letter-spacing: .08em;
}
.qz-number {
  color: #a0aaba;
  font-size: 12px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}
.qz-question {
  margin: 0 0 18px;
  padding: 0 0 17px;
  border-bottom: 1px solid #edf0f4;
  color: #202d3d;
  font-size: 19px;
  line-height: 1.65;
  font-weight: 760;
  letter-spacing: .005em;
}
.qz-options { margin: 0 0 16px; }
.option {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  width: 100%;
  margin: 0 0 9px;
  padding: 12px 14px;
  border: 1px solid #e5eaf0;
  border-radius: 13px;
  background: #ffffff;
  color: #344256;
  font-size: 15px;
  line-height: 1.62;
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, box-shadow .16s ease, transform .16s ease;
}
.option:hover {
  border-color: #bfd3df;
  background: #f8fbfd;
  box-shadow: 0 4px 14px rgba(71, 109, 133, .06);
}
.option-label, .opt-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  border: 1px solid #c9d5df;
  border-radius: 10px;
  background: #f8fafc;
  color: #5f7184;
  font-size: 13px;
  line-height: 1;
  font-weight: 800;
}
.option-text, .opt-text { flex: 1; padding-top: 2px; }
.opt-input { display: none !important; }
.qz-options > .reset-radio,
.qz-options > .reset-btn,
.qz-options > .submit-check,
.qz-options > .submit-btn { display: none !important; }
.option:has(.opt-input:checked) {
  border-color: #9fc4d8;
  background: #eef7fc;
  box-shadow: 0 0 0 2px rgba(159, 196, 216, .15);
}
.option:has(.opt-input:checked) .option-label {
  border-color: #7eaac3;
  background: #8eb8cf;
  color: #ffffff;
}
.answer-toggle { display: none !important; }
.quiz-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 15px 0 2px;
}
.action-primary, .action-secondary {
  appearance: none;
  -webkit-appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  padding: 8px 17px;
  border-radius: 11px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 760;
  line-height: 1;
  cursor: pointer;
  transition: transform .14s ease, box-shadow .14s ease, background .14s ease;
}
.action-primary {
  border: 1px solid #769fb7;
  background: #7fa9c1;
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(82, 128, 153, .14);
}
.action-primary:hover { background: #739db5; }
.action-secondary {
  border: 1px solid #e1e6ec;
  background: #f7f9fb;
  color: #667588;
}
.action-secondary:hover { background: #f0f4f7; }
.action-primary:active, .action-secondary:active { transform: translateY(1px); }
.answer-reveal {
  display: none;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid #e7edf2;
}
.quiz-card:has(#answer-toggle:checked) .answer-reveal {
  display: block;
  animation: qzFade .22s ease-out;
}
.quiz-card:has(#answer-toggle:checked) .option.is-correct,
.card-back .option.is-correct {
  border-color: #a9d2bf !important;
  background: #eef8f2 !important;
  box-shadow: 0 0 0 2px rgba(118, 174, 145, .09) !important;
}
.quiz-card:has(#answer-toggle:checked) .option.is-correct .option-label,
.card-back .option.is-correct .option-label {
  border-color: #86b69e !important;
  background: #93bea8 !important;
  color: #ffffff !important;
}
.quiz-card:has(#answer-toggle:checked) .option:has(.opt-input:checked):not(.is-correct) {
  border-color: #e1b8bb !important;
  background: #fff3f3 !important;
}
.quiz-card:has(#answer-toggle:checked) .option:has(.opt-input:checked):not(.is-correct) .option-label {
  border-color: #c99096 !important;
  background: #d79ca1 !important;
  color: #ffffff !important;
}
.quiz-card:has(#answer-toggle:checked) .option:not(.is-correct):not(:has(.opt-input:checked)),
.card-back .option.dim { opacity: .5; }
.ans-badge {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  margin: 0 0 8px;
  padding: 3px 9px;
  border: 0;
  border-radius: 999px;
  background: #eef5f9;
  color: #597b91;
  font-size: 12px;
  font-weight: 780;
  letter-spacing: .03em;
}
.ans-badge-analysis { font-size: 0; }
.ans-badge-analysis::after { content: "解析"; font-size: 12px; }
.ans-text {
  display: inline-flex;
  align-items: center;
  min-width: 38px;
  min-height: 34px;
  margin: 0 0 16px 7px;
  padding: 5px 11px;
  border-radius: 10px;
  background: #edf7f1;
  color: #47745e;
  font-size: 17px;
  font-weight: 820;
  vertical-align: middle;
}
.exp-block {
  margin-top: 4px;
  color: #344357;
  font-size: 15px;
  line-height: 1.88;
}
.exp-block .ans-badge-answer,
.exp-block .ans-badge-answer + .ans-answer,
.exp-block .ans-badge-answer + .ans-para { display: none !important; }
.ans-para { margin: 9px 0; }
.point-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  margin-right: 7px;
  padding: 0 6px;
  border-radius: 7px;
  background: #f0f3f7;
  color: #7a899a;
  font-size: 11px;
  line-height: 1;
  font-weight: 780;
  vertical-align: 1px;
}
.key-point, .em-blue {
  padding: .08em .32em;
  border-radius: 6px;
  background: #e7f2f9;
  color: #365f78;
  font-weight: 800;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}
.law-ref, .highlight {
  padding: .07em .30em;
  border-radius: 6px;
  background: #fff2bd;
  color: #66571d;
  font-weight: 760;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}
.rule-em {
  color: #334f64;
  font-weight: 800;
  text-decoration-line: underline;
  text-decoration-color: #9fc6dc;
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
  text-decoration-skip-ink: auto;
}
.opt-ref, .opt-ref-badge {
  color: #557a93;
  font-weight: 800;
}
.opt-ref-badge {
  display: inline-flex;
  align-items: center;
  min-height: 27px;
  padding: 2px 9px;
  border-radius: 8px;
  background: #eef5f9;
}
.ans-conclusion {
  margin: 13px 0 2px;
  padding: 10px 12px;
  border-left: 3px solid #9dbfd3;
  border-radius: 8px 11px 11px 8px;
  background: #f1f7fb;
  color: #3c5669;
  font-weight: 680;
}
.qz-source {
  margin-top: 18px;
  padding-top: 12px;
  border-top: 1px dashed #dfe6ed;
  color: #a0aab7;
  font-size: 11px;
  line-height: 1.55;
  word-break: break-word;
}
.card-back .option { cursor: default; }
.card-back .quiz-controls { display: none; }
@keyframes qzFade {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}
@media (max-width: 520px) {
  .card { padding: 8px 6px 22px; font-size: 15px; }
  .quiz-card { padding: 18px 15px 17px; border-radius: 15px; box-shadow: none; }
  .qz-top-line { margin: -18px -15px 15px; }
  .qz-question { font-size: 18px; }
  .option { padding: 11px 12px; border-radius: 12px; }
  .option-label { flex-basis: 28px; width: 28px; height: 28px; }
  .quiz-controls { display: grid; grid-template-columns: 1fr 1fr; }
  .action-primary, .action-secondary { width: 100%; }
}
.nightMode.card { background: #171b20; color: #dce3ea; }
.nightMode .quiz-card { background: #20262d; border-color: #303842; box-shadow: none; }
.nightMode .qz-question { color: #edf2f7; border-color: #333c46; }
.nightMode .option { background: #242b33; border-color: #36414c; color: #d8e0e8; }
.nightMode .option-label { background: #2a333c; border-color: #465461; color: #bac5cf; }
.nightMode .action-secondary { background: #29313a; border-color: #3c4651; color: #d0d8df; }
.nightMode .exp-block { color: #d4dde6; }
.nightMode .ans-conclusion { background: #25333d; color: #d1e1eb; }
.nightMode .qz-source { border-color: #3a444f; color: #8996a3; }
.anki-audio, .anki-video { display: block; width: 100%; max-width: 100%; margin: 0.5rem 0; }
.anki-media-missing { display: block; margin: 0.35rem 0; color: #9f1239; font-size: 0.875rem; }
.anki-math-source,
.anki-math-rendered {
  display: inline-block;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  vertical-align: middle;
  -webkit-overflow-scrolling: touch;
}
.anki-math-source {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  white-space: pre-wrap;
}
.anki-math-source[data-anki-math="display"],
.anki-math-rendered[data-anki-math="display"] {
  display: block;
  margin: 0.75rem 0;
  text-align: center;
}
.anki-math-rendered math {
  max-width: 100%;
}
@media (max-width: 767px) {
  .anki-math-source,
  .anki-math-rendered {
    width: 100%;
    max-width: 100%;
    text-align: left;
  }
}
.miki-apkg-card { box-sizing: border-box; width: 100%; max-width: 980px; margin: 0 auto; color: #111827; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; line-height: 1.85; }
.miki-apkg-card * { box-sizing: border-box; }
.miki-apkg-topbar { display: flex; justify-content: center; gap: 12px; margin: 6px 0 22px; }
.miki-apkg-tab { display: inline-flex; align-items: center; gap: 8px; padding: 8px 16px; border-radius: 12px; background: #f4f7fb; color: #2563eb; font-weight: 800; }
.miki-apkg-badge { min-width: 20px; height: 20px; padding: 0 7px; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; background: #ef4444; color: #fff; font-size: 12px; font-weight: 900; }
.miki-apkg-control { display: flex; justify-content: center; margin: -8px 0 24px; }
.miki-apkg-control-pill { border: 0; border-radius: 999px; padding: 9px 22px; background: #39d486; color: #fff; font-weight: 900; }
.miki-apkg-question { margin: 0 auto 24px; max-width: 980px; font-size: 16px; font-weight: 750; line-height: 2; }
.miki-apkg-question-type { color: #007aff; font-weight: 900; margin-right: 4px; }
.miki-apkg-options { margin: 22px auto 18px; max-width: 980px; display: grid; gap: 12px; }
.miki-apkg-option { display: flex; align-items: flex-start; gap: 10px; width: 100%; min-height: 46px; border: 1.5px solid #1f2937; border-radius: 6px; padding: 10px 14px; background: #fff; color: #111827; font-size: 15px; font-weight: 700; cursor: pointer; }
.miki-apkg-option input { flex: 0 0 auto; margin-top: 6px; }
.miki-apkg-option-letter { flex: 0 0 auto; font-weight: 900; }
.miki-apkg-option-text { flex: 1 1 auto; }
.miki-apkg-source-pills { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px auto 0; max-width: 980px; }
.miki-apkg-pill { display: inline-flex; align-items: center; border: 1.5px solid #1e90ff; border-radius: 5px; background: #eff6ff; padding: 6px 10px; color: #007aff; font-size: 14px; font-weight: 850; line-height: 1.55; }
.miki-apkg-back { max-width: 980px; margin: 0 auto; }
.miki-apkg-back-title { margin: 0 0 12px; font-size: 15px; font-weight: 900; color: #007aff; }
.miki-apkg-section { margin: 14px 0; padding: 14px 16px; border-radius: 14px; background: #f8fafc; border: 1px solid #e5e7eb; }
.miki-apkg-section h3 { margin: 0 0 8px; font-size: 14px; color: #2563eb; }
.miki-apkg-section-content { font-size: 15px; line-height: 1.85; }
.miki-anki-readable-fallback { padding: 16px; color: #111827; line-height: 1.85; white-space: pre-wrap; }
